record.field:
{
    "properties": {
        "name": {
            "type": "string",
            "description": "Title/name of the lead"
        },
        "description": {
            "type": "string",
            "description": "Description or notes about the lead"
        },
        "partner_id": {
            "type": "number",
            "description": "ID of the related customer/partner (optional)"
        },
        "team_id": {
            "type": "number",
            "description": "ID of the sales team to assign (optional)"
        }
    },
    "required": ["name", "description"],
    "type": "object"
}

{
    "properties": {
        "assessment": {
            "type": "string",
            "description": "Complete structured risk assessment text including overall risk level (Low/Medium/High), financial risk, supply-chain risk, strategic risk, and recommended action."
        }
    },
    "required": ["assessment"],
    "type": "object"
}

{
    "properties": {
        "sentiment_summary": {
            "type": "string",
            "description": "Complete sentiment analysis including overall tone, per-message emotional labels, identified outliers, and an actionable relationship summary."
        }
    },
    "required": ["sentiment_summary"],
    "type": "object"
}
